from controller_manager import activate_controllers, list_controllers, bcolors

from ros2cli.node.direct import add_arguments
from ros2cli.node.strategy import NodeStrategy
from ros2cli.verb import VerbExtension

from ros2controlcli.api import add_controller_mgr_parsers, LoadedControllerNameCompleter


class ActivateControllersVerb(VerbExtension):
    """Activate controllers in a controller manager with automatic conflict resolution."""

    def add_arguments(self, parser, cli_name):
        add_arguments(parser)
        arg = parser.add_argument(
            "controller_names",
            nargs="*",
            help="Name of the controllers to be activated",
        )
        arg.completer = LoadedControllerNameCompleter(["inactive"])
        strictness_group = parser.add_mutually_exclusive_group(required=False)
        strictness_group.add_argument(
            "--strict",
            help="Set the activate_controllers service strictness to strict",
            action="store_true",
        )
        strictness_group.add_argument(
            "--best-effort",
            help="Set the activate_controllers service strictness to best effort",
            action="store_true",
        )
        add_controller_mgr_parsers(parser)

    def main(self, *, args):
        with NodeStrategy(args).direct_node as node:
            strict = args.strict
            response = activate_controllers(
                node,
                args.controller_manager,
                args.controller_names,
                strict,
            )
            if not response.ok:
                print(bcolors.FAIL + "Failed to activate controllers" + bcolors.ENDC)
                return 1

            print(bcolors.OKBLUE + "Successfully activated controllers" + bcolors.ENDC)

            # List all active controllers
            controller_list = list_controllers(node, args.controller_manager, 5.0).controller
            active_controllers = [c.name for c in controller_list if c.state == "active"]
            if active_controllers:
                print(bcolors.OKCYAN + "Currently active controllers: " + ", ".join(active_controllers) + bcolors.ENDC)
            return 0
